with valid as (select *, lower(merchant) as merchant_lower, coalesce(merchant, 'UNKNOWN') as resolved_merchant from transactions where merchant is not distinct from 'Lazada' and is_flagged), gaps as (select *, case when lag(txn_time) over (partition by account_id order by txn_time, id) is null or txn_time > lag(txn_time) over (partition by account_id order by txn_time, id) + interval '30' day then 1 else 0 end as session_start_flag from valid), islands as (select id, account_id, txn_type, txn_time, merchant, is_flagged, resolved_merchant, sum(session_start_flag) over (partition by account_id order by txn_time, id rows between unbounded preceding and current row) as island_id from gaps) select date_trunc('week', txn_time) as week_start, merchant, account_id, max(txn_time) as last_seen, count(*) filter (where txn_type = 'FEE') as fee_rows, sum(case when txn_type = 'FEE' then island_id else 0 end) as fee_island_id, round(avg(island_id), 2) as avg_island_id, grouping_id() as gid from islands group by grouping sets ((date_trunc('week', txn_time), merchant, account_id), (date_trunc('week', txn_time), merchant), (date_trunc('week', txn_time)))
